/**
 * @param {Function} fn
 * @return {Function}
 */
function memoize(fn) {
    const cache = new Map(); // serialized args -> result

    return function(...args) {
        const key = JSON.stringify(args);          // order- and type-sensitive key
        if (cache.has(key)) return cache.get(key); // hit: do not call fn
        const result = fn.apply(this, args);       // miss: compute once
        cache.set(key, result);
        return result;
    };
}

/**
 * let callCount = 0;
 * const memoizedFn = memoize(function (a, b) {
 *	 callCount += 1;
 *   return a + b;
 * })
 * memoizedFn(2, 3) // 5
 * memoizedFn(2, 3) // 5
 * console.log(callCount) // 1
 */
